import{_ as e,o as s,c as n,a2 as i}from"./chunks/framework.ClgMjOt7.js";const h=JSON.parse('{"title":"アーキテクチャ概要","description":"Palleria の全体レイヤー構造、モジュール構成、使用技術スタック","frontmatter":{"title":"アーキテクチャ概要","description":"Palleria の全体レイヤー構造、モジュール構成、使用技術スタック"},"headers":[],"relativePath":"architecture/index.md","filePath":"architecture/index.md","lastUpdated":1786166106000}'),o={name:"architecture/index.md"};function l(t,a,p,c,d,r){return s(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="アーキテクチャ概要" tabindex="-1">アーキテクチャ概要 <a class="header-anchor" href="#アーキテクチャ概要" aria-label="Permalink to &quot;アーキテクチャ概要&quot;">​</a></h1><p>Palleria は、Kotlin (Jetpack Compose) による UI・ドメイン層と、Rust による通信・API パース層からなるアーキテクチャで構成されています。</p><hr><h2 id="システム構成" tabindex="-1">システム構成 <a class="header-anchor" href="#システム構成" aria-label="Permalink to &quot;システム構成&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                   UI Layer (Kotlin)                    │</span></span>
<span class="line"><span>│  - Jetpack Compose + Miuix KMP Components              │</span></span>
<span class="line"><span>│  - Navigation / ViewModels (StateFlow / Coroutines)    │</span></span>
<span class="line"><span>└───────────────────────────┬────────────────────────────┘</span></span>
<span class="line"><span>                            │</span></span>
<span class="line"><span>┌───────────────────────────▼────────────────────────────┐</span></span>
<span class="line"><span>│                Data &amp; Local Storage Layer              │</span></span>
<span class="line"><span>│  - Room DB (Account, View/Search History, SavedIllust) │</span></span>
<span class="line"><span>│  - DataStore (AppSettings / SettingsStore)             │</span></span>
<span class="line"><span>│  - PallaSync Engine (暗号化バックアップ &amp; 同期)        │</span></span>
<span class="line"><span>└───────────────────────────┬────────────────────────────┘</span></span>
<span class="line"><span>                            │ (JNI via UniFFI)</span></span>
<span class="line"><span>┌───────────────────────────▼────────────────────────────┐</span></span>
<span class="line"><span>│                 Rust Core (pixiv-api)                  │</span></span>
<span class="line"><span>│  - Transport Bridge (OkHttp / Rust Client)             │</span></span>
<span class="line"><span>│  - Serde JSON Decoder (バッファサイズ上限制御)         │</span></span>
<span class="line"><span>│  - DTO &amp; Domain Model Mapping                          │</span></span>
<span class="line"><span>└────────────────────────────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="主要パッケージ構成-com-yunfie-illustia" tabindex="-1">主要パッケージ構成 (<code>com.yunfie.illustia</code>) <a class="header-anchor" href="#主要パッケージ構成-com-yunfie-illustia" aria-label="Permalink to &quot;主要パッケージ構成 (\`com.yunfie.illustia\`)&quot;">​</a></h2><ul><li><code>account</code>: ログイン処理、OAuth2 トークン取得・管理</li><li><code>data</code>: リポジトリ層 (<code>IllustiaRepository</code>, <code>ManagedDataRepository</code>), API クライアント (<code>RustPixivHttpClient</code>), Room 連携</li><li><code>models</code>: UI およびデータレイヤーで共有するデータモデル群 (<code>Illust</code>, <code>UserProfile</code>, <code>SearchTarget</code> 等)</li><li><code>nativebridge</code>: UniFFI により生成された Rust との JNI バインディング層</li><li><code>pallasync</code>: 設定およびステートの暗号化同期・復元エンジン</li><li><code>settings</code>: <code>AppSettings</code> 定義、DataStore 処理 (<code>SettingsStore</code>), Room DB エンティティ定義 (<code>settings/db/</code>)</li><li><code>ui</code>: Compose 画面 (<code>ui/screens/</code>) および共通 UI コンポーネント (<code>ui/components/</code>)</li><li><code>viewmodel</code>: 各画面の StateFlow / State を保持する ViewModel</li><li><code>wallpaper</code>: ライブ壁紙サービス (<code>PalleriaLiveWallpaperService</code>)</li><li><code>widget</code>: アプリウィジェットプロバイダ (<code>IllustWidgetProvider</code>, <code>RankingWidgetProvider</code>)</li></ul>`,8)])])}const m=e(o,[["render",l]]);export{h as __pageData,m as default};
